INSERT INTO `Assessment` VALUES (1,'lovetri','爱情三角','','恋爱测评','基于 Sternberg 爱情三角理论，从亲密、激情、承诺三个维度出发，生成你的专属爱情三角形态，并匹配 7 种爱情类型之一。测一测，看看你的爱属于哪一种。','本测评共 12 题，请根据您当前（或最近一段）亲密关系的真实感受作答，没有对错之分。','#EC4899','triangle','[{\"id\":\"love_i_1\",\"type\":\"scale\",\"title\":\"我能与伴侣分享内心深处的想法和感受\",\"dimension\":\"intimacy\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_i_2\",\"type\":\"scale\",\"title\":\"我与伴侣之间的关系非常亲密\",\"dimension\":\"intimacy\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_i_3\",\"type\":\"scale\",\"title\":\"伴侣理解并支持我的情感需求\",\"dimension\":\"intimacy\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_i_4\",\"type\":\"scale\",\"title\":\"我可以毫无保留地向伴侣倾诉烦恼\",\"dimension\":\"intimacy\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_p_1\",\"type\":\"scale\",\"title\":\"只要想到伴侣，我就会感到兴奋和心跳加速\",\"dimension\":\"passion\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_p_2\",\"type\":\"scale\",\"title\":\"与伴侣在一起时，我常常感到激情澎湃\",\"dimension\":\"passion\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_p_3\",\"type\":\"scale\",\"title\":\"我被伴侣深深吸引，难以抗拒\",\"dimension\":\"passion\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_p_4\",\"type\":\"scale\",\"title\":\"我渴望与伴侣有亲密的身体接触\",\"dimension\":\"passion\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_c_1\",\"type\":\"scale\",\"title\":\"我决定与伴侣共同走过一生\",\"dimension\":\"commitment\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_c_2\",\"type\":\"scale\",\"title\":\"我愿意为维护这段关系承担责任\",\"dimension\":\"commitment\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_c_3\",\"type\":\"scale\",\"title\":\"即使遇到困难，我也愿意坚持这段关系\",\"dimension\":\"commitment\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}},{\"id\":\"love_c_4\",\"type\":\"scale\",\"title\":\"我对这段关系的未来充满信心\",\"dimension\":\"commitment\",\"required\":true,\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}],\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"}}]','[{\"code\":\"intimacy\",\"label\":\"亲密\",\"desc\":\"情感连接、理解支持与心灵共鸣，是爱情中「温暖」的部分（Sternberg: Intimacy）\"},{\"code\":\"passion\",\"label\":\"激情\",\"desc\":\"生理吸引、浪漫心动与渴望，是爱情中「热烈」的部分（Sternberg: Passion）\"},{\"code\":\"commitment\",\"label\":\"承诺\",\"desc\":\"长久决定、责任承担与共同规划，是爱情中「坚定」的部分（Sternberg: Commitment）\"}]','{\"code\":\"lovetri\",\"dimensionLabels\":{\"intimacy\":\"亲密\",\"passion\":\"激情\",\"commitment\":\"承诺\"},\"templates\":{\"满分式爱情\":{\"key\":\"满分式爱情\",\"title\":\"满分式爱情（Consummate Love）\",\"summary\":\"亲密、激情、承诺三柱齐燃，是爱情最理想也最珍贵的圆满形态。\",\"overview\":\"你是爱情里「最难能可贵」的模样——亲密、激情、承诺三根支柱稳稳撑起你心中的理想之爱。你既能毫无保留地靠近对方，也敢于许下长久的约定，还始终保有让爱持续发光的热情。这不是运气，而是你懂经营、愿投入、肯珍惜的结果。\",\"strengths\":[\"你是爱情里的“全能型选手”——亲密、激情、承诺三根支柱齐备，这是许多人向往的理想状态。\",\"你既懂得敞开心扉分享内心，也敢于许下长久的承诺，还能让爱持续保持温度，经营能力令人欣赏。\",\"你的爱完整而稳定，能给伴侣一种“被稳稳接住”的安心感，这是关系里最珍贵的底气。\"],\"growthPoints\":[\"圆满也需要“保鲜”。定期为关系制造新鲜感，让美好的相处习惯持续发光。\",\"给彼此留一点独立呼吸的空间，适度的距离会让爱更有弹性和生命力。\",\"允许关系有自然的起伏，偶尔的不完美，反而会让爱更真实、更可爱。\"],\"relationships\":\"圆满是持续经营的起点。定期为关系注入新鲜感，也给彼此留一点独立呼吸的空间，爱会更有弹性、更长久。\"},\"心动式爱情\":{\"key\":\"心动式爱情\",\"title\":\"心动式爱情（Romantic Love）\",\"summary\":\"亲密与激情交织，浪漫四溢，是一场不会散场的玫瑰色心动。\",\"overview\":\"你是“一眼心动”的浪漫主义者。亲密与激情让你爱得热烈又深情，你会记住每一个值得纪念的瞬间，也会为对方准备不期而遇的惊喜。你的爱像一杯微醺的红酒，甜而不腻，让人忍不住沉溺。\",\"strengths\":[\"你拥有“让人心动”的天赋，浪漫是你的本能，惊喜和仪式感是你的拿手好戏。\",\"你爱得热烈又深情，能让平淡的日子因为你的存在而闪闪发光。\",\"你善于表达爱意，从不吝啬赞美与温柔，和你在一起的人总觉得自己被认真爱着。\"],\"growthPoints\":[\"在浪漫的心动里，试着和对方聊聊关于未来的想象，让热烈也能落地生根。\",\"把“今天好爱你”变成“我会一直在这里”，用小小的约定为感情增添笃定感。\",\"日常里的陪伴与承诺，是让心动持续发光的温柔底色。\"],\"relationships\":\"浪漫的心动很珍贵，试着在对未来的憧憬里也加上彼此的身影，让热烈不仅在当下绽放，也能稳稳地延续下去。\"},\"长情式爱情\":{\"key\":\"长情式爱情\",\"title\":\"长情式爱情（Companionate Love）\",\"summary\":\"亲密与承诺充沛，是细水长流、温暖守护的伴侣之爱。\",\"overview\":\"你是“细水长流”的陪伴者。亲密与承诺让你愿意把对方请进生命里，一起分享琐碎、一起面对风雨。你的爱不轰轰烈烈，却像一盏始终亮着的灯，让人安心，也让人笃定“原来有人一直都在”。\",\"strengths\":[\"你是关系里最可靠的港湾，细水长流的陪伴，让伴侣随时都有“家”的安心感。\",\"你擅长倾听与守护，懂得在生活的细节里传递温度，让爱渗透进每个平凡日常。\",\"你对承诺的坚守，让爱经得起时间的考验——你的爱人可以放心地依靠你。\"],\"growthPoints\":[\"长久的陪伴里，也记得为彼此制造一点心动时刻，让熟悉的日子重新升温。\",\"试着把藏在行动里的在乎，用一句走心的情话或一个拥抱表达出来。\",\"和伴侣一起尝试一件新鲜事，稳定的关系也可以拥有新鲜的冒险感。\"],\"relationships\":\"细水长流的陪伴是一种福气，也记得偶尔制造一点心跳时刻，让熟悉的日子继续升温。\"},\"热恋式爱情\":{\"key\":\"热恋式爱情\",\"title\":\"热恋式爱情（Fatuous Love）\",\"summary\":\"激情与承诺并立，爱得果断而炽烈，是飞蛾扑火般的勇敢。\",\"overview\":\"你是“说走就走”的热烈行动派。激情与承诺让你爱得果断而炽烈，认定一个人就愿意立刻把真心交付。你渴望轰轰烈烈，也会为爱奋不顾身，这股冲劲，是很多人羡慕也做不到的勇气。\",\"strengths\":[\"你有一往无前的爱的勇气，认定一个人就愿意立刻交付真心，这份果断令人羡慕。\",\"你是行动派爱人，说到做到，愿意为关系投入全部热情与精力。\",\"和你在一起，永远不缺少热烈与冲劲，你的爱能把平凡生活点燃成烟火。\"],\"growthPoints\":[\"在热烈与笃定之间，试着多走进彼此的内心，让“认定”也包含“懂得”。\",\"每天留一点时间分享彼此的心情与日常，亲密会在这些细碎里慢慢生长。\",\"你们的激情与承诺已经是很好的起点，再添上深入的亲密，爱会更圆满。\"],\"relationships\":\"炽热与笃定都很珍贵，试着在日常里多分享、多倾听，让承诺扎根在真实的懂得里，爱会燃烧得更稳、更久。\"},\"知己式爱情\":{\"key\":\"知己式爱情\",\"title\":\"知己式爱情（Liking）\",\"summary\":\"亲密有余、激情与承诺不足，你们是彼此最懂的人。\",\"overview\":\"你是“灵魂共鸣”的知己型。亲密让你拥有走进对方内心的能力，你懂 ta 的欢喜与脆弱，也能毫无负担地坦诚相待。在你这里，爱是先“懂”而后“爱”，这种深刻的默契，珍贵又动人。\",\"strengths\":[\"你是天生的“灵魂伴侣”，能走进对方内心最柔软的地方，让人被深深理解。\",\"你懂得倾听与共情，和你相处的人总能卸下防备，做真实的自己。\",\"这份纯粹的理解与默契，是很多关系求之不得的珍贵礼物。\"],\"growthPoints\":[\"你已经是很好的倾听者，试着也让对方看见你心动的一面，靠近会更有温度。\",\"当感情成熟时，不妨和对方聊聊对未来的期待，把默契轻轻变成约定。\",\"给彼此创造一点专属的浪漫时刻，让“懂”升华为“恋”。\"],\"relationships\":\"你擅长让人被理解，也试着让对方看见你心动的一面。把默契轻轻变成靠近，爱情就有了更温柔的入口。\"},\"火花式爱情\":{\"key\":\"火花式爱情\",\"title\":\"火花式爱情（Infatuated Love）\",\"summary\":\"激情主导，像绚烂烟火，来得快、燃得烈。\",\"overview\":\"你是“一见倾心”的激情主导者。你的爱像一场绚烂的烟火，来得快、燃得烈，充满吸引力与生命力。你享受心动瞬间的悸动，也愿意为喜欢的人勇敢表达，这份热忱让平淡的生活瞬间被点亮。\",\"strengths\":[\"你的爱像烟火般绚烂，充满不可抗拒的吸引力，让人一见难忘。\",\"你敢于表达心动，敢爱敢追，让关系始终充满电光石火的活力。\",\"你的热情是关系最明亮的开场，和你在一起的人，每一天都可能被惊喜点亮。\"],\"growthPoints\":[\"心动是很好的开始，试着多走进对方的生活与内心，让热烈有更深的连接。\",\"在约会与惊喜之外，也一起分享日常琐事，亲密往往藏在最平凡的对话里。\",\"当感情稳定时，和对方一起描绘未来的画面，承诺会让激情更有方向感。\"],\"relationships\":\"心动的烟火很亮，若能在日常里慢慢扎根，它会成为关系里最温暖的长明灯火。\"},\"坚守式爱情\":{\"key\":\"坚守式爱情\",\"title\":\"坚守式爱情（Empty Love）\",\"summary\":\"承诺坚定，是爱情里最稀缺的稳定力量。\",\"overview\":\"你是“一诺千金”的责任型。承诺让你在关系里异常可靠，你会把“在一起”认真当成一种责任来坚守。你不轻易开始，但一旦认定，就会用行动去兑现那句承诺——这种担当，是爱情里最稀缺的稳定力量。\",\"strengths\":[\"你是爱情里最稀缺的“稳定力量”，一诺千金、言行一致，让人从骨子里感到踏实。\",\"你把责任稳稳扛在肩上，用日复一日的行动证明，爱不是说说而已。\",\"你的可靠是关系穿越风浪的压舱石，你的爱人可以永远相信你的选择。\"],\"growthPoints\":[\"你的可靠是珍贵的，试着在责任之外，也主动表达温柔与想念。\",\"每天花一点时间和伴侣分享彼此的一天，让亲密在细小处重新流动。\",\"偶尔制造一个浪漫或轻松的约会，让承诺既有安全感，也有心动感。\"],\"relationships\":\"你的担当让人安心，记得也给关系加一点温柔与惊喜，让承诺被爱意包裹着生长。\"}}}','published',1,12,'2026-08-26 15:12:17.782','2026-08-27 06:54:37.430',0),(2,'las','爱情态度量表','Love Attitude Scale','恋爱测评','基于 Hendrick & Hendrick 爱情态度理论（Love Attitude Scale），从浪漫、游戏、同伴、现实、占有、奉献六种爱情色彩，帮您看清自己在爱情中的真实态度与倾向。','本测评共 42 题，请根据您当前（或最近一段）亲密关系的真实感受作答，用「非常不同意」到「非常同意」描述您对每句话的认同程度，没有对错之分。','#8B5CF6','heart','[{\"id\":\"las_q1\",\"type\":\"scale\",\"title\":\"我和他/她属于一见钟情型。\",\"dimension\":\"eros\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q11\",\"type\":\"scale\",\"title\":\"我和他/她很来电。\",\"dimension\":\"eros\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q15\",\"type\":\"scale\",\"title\":\"我和他/她的亲密行为是很热情且很令我满意。\",\"dimension\":\"eros\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q22\",\"type\":\"scale\",\"title\":\"我觉得我和他/她是天生一对。\",\"dimension\":\"eros\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q27\",\"type\":\"scale\",\"title\":\"我和他/她的感情、亲密行为进展得很快。\",\"dimension\":\"eros\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q33\",\"type\":\"scale\",\"title\":\"我和他/她非常了解彼此。\",\"dimension\":\"eros\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q36\",\"type\":\"scale\",\"title\":\"他/她的外貌符合我的理想标准。\",\"dimension\":\"eros\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q2\",\"type\":\"scale\",\"title\":\"我很难明确地说我和他/她是何时从友情变成爱情的。\",\"dimension\":\"storge\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q12\",\"type\":\"scale\",\"title\":\"我需要先经过一阵子的关心和照顾，才有可能产生爱情。\",\"dimension\":\"storge\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q19\",\"type\":\"scale\",\"title\":\"我希望和曾经相爱的他/她是永远的朋友。\",\"dimension\":\"storge\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q21\",\"type\":\"scale\",\"title\":\"我和他/她的爱情关系是最理想的，因为是由长久的友谊发展而成的。\",\"dimension\":\"storge\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q28\",\"type\":\"scale\",\"title\":\"我和他/她的友情随着时间逐渐转变为爱情。\",\"dimension\":\"storge\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q31\",\"type\":\"scale\",\"title\":\"我和他/她的爱情是一种深刻的友情，而不是一种很神秘的情感。\",\"dimension\":\"storge\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q42\",\"type\":\"scale\",\"title\":\"我和他/她的爱情关系是最令人满意的，因为是由良好友情发展成的。\",\"dimension\":\"storge\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q3\",\"type\":\"scale\",\"title\":\"对他/她做承诺之前，我会考虑他/她将来可能变成的样子。\",\"dimension\":\"pragma\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q7\",\"type\":\"scale\",\"title\":\"在选择他/她之前，我会先试着仔细规划我的人生。\",\"dimension\":\"pragma\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q13\",\"type\":\"scale\",\"title\":\"我和他/她最好有相似的背景。\",\"dimension\":\"pragma\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q18\",\"type\":\"scale\",\"title\":\"他/她如何看待我的家人是我选择他/她的主要考量。\",\"dimension\":\"pragma\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q24\",\"type\":\"scale\",\"title\":\"他/她将来会不会是一个好父亲/母亲是我选择他/她的一个重要因素。\",\"dimension\":\"pragma\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q35\",\"type\":\"scale\",\"title\":\"他/她如何看待我的职业会是我选择他/她的一个考量。\",\"dimension\":\"pragma\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q39\",\"type\":\"scale\",\"title\":\"在和他/她深入交往之前，我会试着了解他/她是否有良好的遗传基因。\",\"dimension\":\"pragma\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q4\",\"type\":\"scale\",\"title\":\"我总是试着帮他/她渡过难关。\",\"dimension\":\"agape\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q8\",\"type\":\"scale\",\"title\":\"我宁愿自己痛苦，也不愿意让他/她受苦。\",\"dimension\":\"agape\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q25\",\"type\":\"scale\",\"title\":\"除非我先让他/她快乐，否则我不会感到快乐。\",\"dimension\":\"agape\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q30\",\"type\":\"scale\",\"title\":\"我通常愿意牺牲自己的愿望，达成他/她的愿望。\",\"dimension\":\"agape\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q32\",\"type\":\"scale\",\"title\":\"他/她可以任意使用我的东西。\",\"dimension\":\"agape\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q38\",\"type\":\"scale\",\"title\":\"当他/她对我发脾气时，我仍然全心全意、无条件地爱他/她。\",\"dimension\":\"agape\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q40\",\"type\":\"scale\",\"title\":\"为了他/她，我愿意忍受任何事情。\",\"dimension\":\"agape\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q5\",\"type\":\"scale\",\"title\":\"和他/她的关系不太对劲时，我的身体就会不舒服。\",\"dimension\":\"mania\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q9\",\"type\":\"scale\",\"title\":\"失恋时，我会十分沮丧，甚至会有自杀的念头。\",\"dimension\":\"mania\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q16\",\"type\":\"scale\",\"title\":\"我有时会因为想到自己正在谈恋爱而兴奋地睡不着觉。\",\"dimension\":\"mania\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q20\",\"type\":\"scale\",\"title\":\"当他/她不注意我时，我会全身不舒服。\",\"dimension\":\"mania\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q23\",\"type\":\"scale\",\"title\":\"自从和他/她谈恋爱后，我很难专心在其他任何事情上。\",\"dimension\":\"mania\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q34\",\"type\":\"scale\",\"title\":\"当我怀疑他/她和其他人在一起时，我就无法放松。\",\"dimension\":\"mania\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q41\",\"type\":\"scale\",\"title\":\"如果他/她忽略我一阵子，我会做出一些傻事来吸引他/她的注意力。\",\"dimension\":\"mania\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q6\",\"type\":\"scale\",\"title\":\"我试着不给他/她明确的承诺。\",\"dimension\":\"ludus\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q10\",\"type\":\"scale\",\"title\":\"我相信他/她不知道我的一些事，也不会受到伤害。\",\"dimension\":\"ludus\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q14\",\"type\":\"scale\",\"title\":\"有时候，我得防范他/她发现我还有其他情人。\",\"dimension\":\"ludus\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q17\",\"type\":\"scale\",\"title\":\"我可以很容易、很快地忘掉过往的恋情。\",\"dimension\":\"ludus\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q26\",\"type\":\"scale\",\"title\":\"如果他/她知道我和其他人做了某些事，他/她会不高兴。\",\"dimension\":\"ludus\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q29\",\"type\":\"scale\",\"title\":\"当他/她太依赖我时，我会想和他/她疏远一些。\",\"dimension\":\"ludus\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}},{\"id\":\"las_q37\",\"type\":\"scale\",\"title\":\"我享受和他/她及一些不同的情人玩爱情游戏。\",\"dimension\":\"ludus\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"非常不同意\",\"maxLabel\":\"非常同意\",\"type\":\"number\"}}]','[{\"code\":\"eros\",\"label\":\"浪漫型 Eros\",\"desc\":\"激情与一见钟情的吸引（越高越倾向）\"},{\"code\":\"ludus\",\"label\":\"游戏型 Ludus\",\"desc\":\"自由多变、享受追逐（越高越倾向）\"},{\"code\":\"storge\",\"label\":\"同伴型 Storge\",\"desc\":\"由友情发展的深厚情感（越高越倾向）\"},{\"code\":\"pragma\",\"label\":\"现实型 Pragma\",\"desc\":\"理性匹配、条件考量（越高越倾向）\"},{\"code\":\"mania\",\"label\":\"占有型 Mania\",\"desc\":\"浓烈依赖、患得患失（越高越倾向）\"},{\"code\":\"agape\",\"label\":\"奉献型 Agape\",\"desc\":\"无私付出、不求回报（越高越倾向）\"}]','{\"code\":\"las\",\"dimensionLabels\":{\"eros\":\"浪漫型\",\"ludus\":\"游戏型\",\"storge\":\"同伴型\",\"pragma\":\"现实型\",\"mania\":\"占有型\",\"agape\":\"奉献型\"},\"templates\":{\"浪漫型\":{\"key\":\"浪漫型\",\"title\":\"浪漫型 Eros\",\"summary\":\"你的爱始于一眼之间的心动——你是爱情里最像「烟花」的人。\",\"overview\":\"您在爱情态度量表中表现出以**浪漫型（Eros）**为主色的爱情倾向。您的爱，始于一眼之间的心动。您相信来电与直觉，重视外貌与身体层面的吸引，亲密关系进展快、浓度高——明亮、直接、毫不犹豫。激情与浪漫是您爱情中最鲜明的色彩。\",\"strengths\":[\"情感浓烈、敢于表达，关系充满火花与新鲜感\",\"行动力强，认定的事情会毫不犹豫地投入\",\"善于营造浪漫氛围，让关系保持热情\"],\"growthPoints\":[\"浪漫的火花美好，但激情会随时间变化\",\"在心动之外，慢慢认识对方完整的样子\",\"让爱从「放电」走向「懂得」，培养持久的深度连接\"]},\"游戏型\":{\"key\":\"游戏型\",\"title\":\"游戏型 Ludus\",\"summary\":\"你视爱情为一场轻松的游戏——在亲密关系里，你最珍惜的是自由。\",\"overview\":\"您在爱情态度量表中表现出以**游戏型（Ludus）**为主色的爱情倾向。您视爱情为一场轻松的游戏，享受追求与被追求的过程，不喜欢被承诺束缚，来去自如、拿得起放得下。洒脱与自由，是您爱情中最鲜明的底色。\",\"strengths\":[\"轻松洒脱，相处不给人压力\",\"社交能力强，富有魅力与吸引力\",\"拿得起放得下，情绪复原快\"],\"growthPoints\":[\"洒脱有时是一种保护色，试着坦诚一点\",\"若渴望深入的关系，练习「留下来」\",\"被一个人真正了解，并不是束缚\"]},\"同伴型\":{\"key\":\"同伴型\",\"title\":\"同伴型 Storge\",\"summary\":\"你的爱，是从友谊里长出来的——你相信时间，更相信细水长流。\",\"overview\":\"您在爱情态度量表中表现出以**同伴型（Storge）**为主色的爱情倾向。您的爱，是从友谊里长出来的。您信任时间、信任了解，认为最好的爱情始于长久的相处与默契。平淡、可靠、彼此托底，是您爱情中最动人的底色。\",\"strengths\":[\"关系稳定可靠，是值得托付的伴侣\",\"信任与默契深厚，沟通顺畅\",\"不追求刺激，情绪稳定、安全感强\"],\"growthPoints\":[\"偶尔为关系制造一点「意外」与惊喜\",\"在习惯之外，重新点燃心动的感觉\",\"主动创造新鲜体验，让感情保持活力\"]},\"现实型\":{\"key\":\"现实型\",\"title\":\"现实型 Pragma\",\"summary\":\"你的爱，是清醒的选择——爱不仅是感觉，更是认真经营的人生决策。\",\"overview\":\"您在爱情态度量表中表现出以**现实型（Pragma）**为主色的爱情倾向。您的爱，是清醒的选择。您会理性地衡量背景、规划、家庭与未来，希望爱情与人生方向一致。冷静与务实，让您在爱情中少走弯路，也更容易找到契合的伴侣。\",\"strengths\":[\"择偶眼光清醒，关系基础扎实\",\"理性规划，善于经营长期关系\",\"对家庭与未来负责，可靠稳重\"],\"growthPoints\":[\"理性会让您错过一些「感觉」\",\"试着给感性留一点位置\",\"不完美的契合，有时恰恰藏着惊喜\"]},\"占有型\":{\"key\":\"占有型\",\"title\":\"占有型 Mania\",\"summary\":\"你的爱，浓烈得像一场风暴——你不是爱得太多，而是太怕失去。\",\"overview\":\"您在爱情态度量表中表现出以**占有型（Mania）**为主色的爱情倾向。您的爱，浓烈得像一场风暴。您爱得用力、在意得深切，对方的关注与回应会牵动您的全部情绪。这份浓度的背面，是深层的害怕失去与安全感缺失。\",\"strengths\":[\"爱得真挚投入，情感浓度高\",\"对关系忠诚、重视对方\",\"情绪丰富、感受细腻\"],\"growthPoints\":[\"把安全感交还给自己的内心\",\"练习在爱里留出边界，给彼此呼吸的空间\",\"你的完整，不该由另一个人负责\"]},\"奉献型\":{\"key\":\"奉献型\",\"title\":\"奉献型 Agape\",\"summary\":\"你的爱，是无条件的给予——你是爱情里最温柔的守护者。\",\"overview\":\"您在爱情态度量表中表现出以**奉献型（Agape）**为主色的爱情倾向。您的爱，是无条件的给予。您习惯把对方放在自己之前，牺牲自己的愿望成全对方，甚至无怨无悔。无私与温柔，是您爱情中最动人的底色，但也要记得照顾好自己。\",\"strengths\":[\"付出真诚、毫无保留，让对方感到被爱\",\"包容体贴，是治愈系的恋人\",\"忠诚专一，愿意为关系承担\"],\"growthPoints\":[\"付出是爱，学会「被爱」同样是爱\",\"在照顾对方之余，好好照顾自己\",\"健康的关系不是单方面的燃烧，而是相互的照亮\"]},\"_portraits\":{\"eros\":{\"core\":\"你的爱，始于一眼之间的心动。你相信来电与直觉，重视外貌与身体层面的吸引，亲密关系进展快、浓度高——你是爱情里最像「烟花」的人，明亮、直接、毫不犹豫。\",\"tip\":\"浪漫的火花美好，但激情会随时间变化。试着在心动之外，慢慢认识对方完整的样子，让爱从「放电」走向「懂得」。\",\"levels\":{\"倾向明显\":{\"letter\":\"你是爱情里的烟火，明亮、直接、毫不犹豫。那些一见倾心的瞬间、电光石火的心动，都是你生命力的证明。请永远为自己拥有这份热烈而骄傲——多少人一生都在等一次这样的心动，而你拥有靠近它的勇气。真正动人的爱，不只是放电的那一刻，更是放电之后，你愿意慢慢认识一个人完整样子的耐心。\",\"suggestions\":[\"在心动的滤镜之外，花时间了解对方的日常、习惯与脆弱，让「爱上一个人」升级为「懂得一个人」\",\"激情会随时间变化，不妨主动创造新的共同体验，让关系里的新鲜感由你亲手续写\",\"偶尔慢下来：别急着推进关系，让情感的浓度在时间中自然沉淀\"]},\"中等\":{\"letter\":\"你的心里既有浪漫的火焰，也有清醒的理智。你懂得心动的美好，也知道激情需要时间去沉淀——这份平衡，让你既能享受爱的浓度，又不容易被冲动带偏。这是许多人求而不得的成熟。愿你在往后的日子里，继续保持这份敏锐，也偶尔允许自己彻底地、不留余地地心动一次。\",\"suggestions\":[\"为你欣赏的人保留一次「先感受、后分析」的机会，让直觉带你体验一次纯粹的浪漫\",\"把浪漫落实成日常的小仪式：一条留言、一次散步、一场计划外的短途\",\"和伴侣聊聊彼此对「激情」的理解，在差异中找到属于你们的节奏\"]},\"偏低\":{\"letter\":\"你并不以「一见钟情」为先导，你更相信相处中慢慢生长出的好感。这让你的爱少了几分冲动的风险，多了几分踏实的质地。请不必羡慕那些烟花般的热烈——你的心动，藏在某个午后的一句懂得里，藏在长久陪伴生出的默契里，同样珍贵，同样动人。偶尔，也给自己一个被「意外」打动的小机会。\",\"suggestions\":[\"试着回应一次对方不经意的靠近，也许一份惊喜就藏在其中\",\"用「多了解一点」的心态认识新朋友，心动未必只能来自第一眼\",\"回顾一段让你感觉温暖的相处，写下是什么让你慢慢喜欢上对方\"]}}},\"ludus\":{\"core\":\"你视爱情为一场轻松的游戏。你享受追求与被追求的过程，不喜欢被承诺束缚，来去自如、拿得起放得下——在亲密关系里，你最珍惜的是自由。\",\"tip\":\"洒脱是一种保护色。若你想要深入的关系，不妨练习「留下来」：坦诚一点、慢一点，你会发现被一个人真正了解，并不是束缚。\",\"levels\":{\"倾向明显\":{\"letter\":\"你像一阵自由的风，洒脱、有趣、来去自如。你懂得享受关系的轻盈，这是许多人羡慕的天赋。但我也想轻轻告诉你：在所有的游戏与追逐背后，那个偶尔安静下来的你，也许也在期待一份能让自己甘愿停留的深度。真正被一个人了解，从来不是束缚，而是另一种自由。当你准备好，会有一个人值得你留下来。\",\"suggestions\":[\"练习「如实表达」：当你开始在乎一个人，试着说出你的在意，而不是用玩笑带过\",\"选择一段关系时，问问自己：我是因为享受追逐，还是真的想要靠近\",\"给那个「让你愿意慢下来」的人一个机会，不必立刻定义关系，先认真相处\"]},\"中等\":{\"letter\":\"你懂得进退，也懂得投入。你能在关系里享受快乐，也愿意在值得的时候认真起来——这种收放自如，是亲密关系里难得的弹性。你在自由与承诺之间行走，路还没有走完，方向却在慢慢清晰。愿你在保持洒脱的同时，也敢把心门打开一条缝，让真正重要的人走进来。\",\"suggestions\":[\"把「愿意认真」当作一种新的勇敢，试着对在乎的人承诺一件小事\",\"留意自己在关系里「想逃」的瞬间，区分是对方不合适，还是自己的旧习惯\",\"用真诚代替套路：直接、坦诚的表达，反而比技巧更能打动人心\"]},\"偏低\":{\"letter\":\"你对关系认真、专一，不玩暧昧的游戏，也不屑于把感情当消遣。这个时代里，这样的慎重与真诚尤为稀缺，请你为它骄傲。你或许不算最擅长制造热闹的人，但你的深情一旦开启，便是安静而持久的陪伴。偶尔，你也可以放松一点，允许关系以一种更轻盈的方式开始。\",\"suggestions\":[\"在认真之外，试着给初识的人多一次轻松相处的机会，不必一上来就谈「结论」\",\"用幽默和自嘲化解紧张，让关系在自然中升温\",\"相信自己的判断：你不需要变成另一个人，真诚本身就是吸引力\"]}}},\"storge\":{\"core\":\"你的爱，是从友谊里长出来的。你信任时间、信任了解，认为最好的爱情始于长久的相处与默契——你不相信奇迹，你相信细水长流。\",\"tip\":\"平淡可靠是巨大的优势，但偶尔也需要一点「意外」。为关系制造一些惊喜与新鲜感，让习惯之外，多一点点心动。\",\"levels\":{\"倾向明显\":{\"letter\":\"你的爱，是从友谊里长出来的，长久的相处、深厚的默契、彼此托底的信任——这些是你爱情里最坚实的底色。你不追逐烟花，你经营灯火，这份温暖而恒定的爱，是很多人一生都在寻找的港湾。请记得，在平淡可靠的日常里，偶尔也为对方点亮一支小小的烟花，让习惯之外，多一点点心跳。\",\"suggestions\":[\"为关系制造「计划外」的惊喜：一场说走就走的短途，一份出其不意的小礼物\",\"主动聊聊「我们还想去哪里、想成为怎样的我们」，让共同期待为关系充电\",\"把欣赏说出口：你的爱往往做得比说得多，试着用语言让对方听见\"]},\"中等\":{\"letter\":\"你既珍惜细水长流的默契，也保有对新鲜体验的渴望。你知道感情需要经营，也懂得为它注入活力——这份清醒与温度并存的特质，让关系在你手中既安稳又有生气。愿你在平淡与惊喜之间，继续为彼此保留一片可以生长爱意的空间。\",\"suggestions\":[\"每个月为关系安排一件「从未一起做过的事」，让共同记忆持续更新\",\"在习惯性照顾对方之外，也学着接收对方的照顾，让爱双向流动\",\"把「谢谢」「想你」这些小事说出口，让温暖被看见\"]},\"偏低\":{\"letter\":\"你更依赖瞬间的连接与直觉的吸引，不习惯让感情在漫长的相处里慢慢生长。这让你少了几分「慢热」的等待，也多了一份对当下感受的信任。其实深度了解一个人，也会带来意想不到的惊喜——给彼此一点时间，让那些细节里的美好，有机会被你看见。\",\"suggestions\":[\"与喜欢的人相处时，刻意放慢节奏，多问几个「为什么」，让了解发生\",\"尝试一次共同完成的小任务（一起做饭、一起拼装），在协作中拉近距离\",\"记录对方让你感到温暖的三个瞬间，你会发现感情正在悄悄生长\"]}}},\"pragma\":{\"core\":\"你的爱，是清醒的选择。你会理性地衡量背景、规划、家庭与未来，希望爱情与人生方向一致——对你而言，爱不仅是感觉，更是认真经营的人生决策。\",\"tip\":\"理性让你少走弯路，但也会让你错过感性。试着给「感觉」留一点位置，有时候不完美的契合，恰恰藏着惊喜。\",\"levels\":{\"倾向明显\":{\"letter\":\"你爱得清醒而笃定。你懂得衡量契合、规划未来，不轻易被冲动带走，这是许多人在感情里最渴望的成熟与可靠。你选择的不是一时的火花，而是一段经得起时间考验的关系。也请记得：在所有的条件与规划之上，留一点位置给那些无法计算的东西——一个让你心动的瞬间，一次不计得失的靠近。\",\"suggestions\":[\"把「感觉」也写进你的择偶清单：心动是不可替代的长期变量\",\"与伴侣一起制定看得见的未来计划，让理性成为关系的助力而非压力\",\"每周留一段不聊现实、只谈心情的时间，让感性的连接发生\"]},\"中等\":{\"letter\":\"你懂得在感性与理性之间取得平衡，既看感觉，也看长远。你不盲目，也不冷漠，你能在爱情里一边清醒地选择，一边真诚地感受。这份平衡感，让你在关系里既可靠又不失温度。愿你在未来的相处中，继续保持这份清醒，同时允许自己在某个时刻，跟着感觉走一次。\",\"suggestions\":[\"当理性告诉你「合适」、感觉却犹豫时，给自己时间确认心动是否存在\",\"约会时偶尔放下「评估模式」，单纯享受当下的相处\",\"把对未来的规划与对方分享，让对方感受到你是认真的\"]},\"偏低\":{\"letter\":\"你恋爱时不太计算条件，更相信感觉本身。你的爱纯粹而珍贵——不预设框架、不权衡利弊，而是跟随内心靠近一个人。这样的你，更容易体验到爱情本来的样子。当然，适当地看看「长远匹配」也并非功利，而是对关系的一种负责。愿你的纯粹，遇到值得的人。\",\"suggestions\":[\"在相信感觉的同时，也认真聊一次彼此的生活规划，为长久的关系铺路\",\"用直觉选择心动，用沟通确认方向，让两者互为补充\",\"不必为「不够现实」而自责：热情与纯粹，同样是经营关系的力量\"]}}},\"mania\":{\"core\":\"你的爱，浓烈得像一场风暴。你爱得用力、在意得深切，对方的关注与回应会牵动你的全部情绪——你不是爱得太多，而是太怕失去。\",\"tip\":\"把安全感交还给自己的内心，是送给这段关系最好的礼物。练习在爱里留出边界，让彼此都有呼吸的空间；你的完整，不该由另一个人负责。\",\"levels\":{\"倾向明显\":{\"letter\":\"你的爱，浓烈得像一场风暴。你不是爱得太多，而是太怕失去——这份敏感与投入，恰恰说明你爱得有多认真。请先抱抱自己：你没有错，你只是太在乎。当你把一部分注意力从对方身上收回，安放回自己身上，你会发现关系反而更松弛、更安心。你的完整，从来不需要另一个人来负责。\",\"suggestions\":[\"建立属于自己的「充电清单」：运动、爱好、朋友，让情绪有独立出口\",\"焦虑袭来时，先深呼吸再回应：练习延迟表达，给情绪一个缓冲\",\"和伴侣约定一个「安心仪式」：稳定的回应节奏，能缓解双方的不安\"]},\"中等\":{\"letter\":\"你的情感浓度很高，爱得投入、在意得深切，偶尔也会患得患失，但大体上能够自处——这份觉察本身，就是一种成长。你在爱与安全感之间摸索着平衡，每一步都算数。愿你在往后的关系里，慢慢练习把「被爱」的底气建立在自我认可之上，你会发现，安稳可以来自自己。\",\"suggestions\":[\"把「他/她是不是不在乎我」的疑问，换成「我今天想为自己做什么」\",\"允许对方有自己的空间与节奏，信任是关系最好的养分\",\"当你感到不安时，用具体事实而非猜测来与对方沟通\"]},\"偏低\":{\"letter\":\"你在关系里松弛、自信，不轻易被情绪绑架，也不把安全感寄托在别人的回应上。这是非常健康、非常难得的感情状态。因为你能安顿好自己，你给出的爱是轻盈的、自由的，对方也会感到被信任与被尊重。请继续保持这份内心的安稳，也允许自己在深爱时，坦然地表达在乎。\",\"suggestions\":[\"当你在乎一个人时，别吝啬直接表达你的需要与在意\",\"偶尔允许自己「认真投入」到可能失去的程度，爱需要一点冒险\",\"把你维持安全感的方法分享给伴侣，帮对方也建立安心感\"]}}},\"agape\":{\"core\":\"你的爱，是无条件的给予。你习惯把对方放在自己之前，牺牲自己的愿望成全对方，甚至无怨无悔——你是爱情里最温柔的守护者。\",\"tip\":\"付出是爱，学会「被爱」同样是爱。请在照顾对方之余，也好好照顾自己——真正健康的关系，不是单方面的燃烧，而是相互的照亮。\",\"levels\":{\"倾向明显\":{\"letter\":\"你的爱，是无条件的给予。你习惯把对方放在自己之前，为 TA 遮风挡雨、无怨无悔——你是爱情里最温柔的守护者，世界对这样的人，应当温柔以待。但请听我说：爱不是燃烧自己照亮别人的烛火，而是两盏灯互相照亮。学会「被爱」，与学会「给予」同样重要。你付出的每一分好，也值得同等的回响。\",\"suggestions\":[\"每天问自己一次：此刻的我，需要什么？并试着满足自己\",\"练习向对方表达需求、接受对方的照顾，让爱双向流动\",\"在付出之前，先确认这份给予是「我愿意」，而非「我害怕失去」\"]},\"中等\":{\"letter\":\"你愿意为对方付出，也保留着照顾自己的意识——这份平衡，让你既能深情地爱，也能得体地自处。你懂得在给予中保护自己，这是一种温柔而清醒的能力。愿你在往后的关系里，继续把这份平衡延伸得更深：让每一次付出都出于心甘情愿，也让每一份爱都留有回响。\",\"suggestions\":[\"把「照顾自己」写进你的日常清单，像照顾对方一样照顾自己\",\"当付出让你感到疲惫时，停下来和伴侣坦诚沟通你的感受\",\"接受赞美与好意，练习大方地「被爱」\"]},\"偏低\":{\"letter\":\"你爱得有所保留，懂得保护自己，不轻易把全部交出去——这份边界感与清醒，是健康的感情里不可缺少的能力。你不必为自己「不够无私」而怀疑，因为在爱里，先站稳自己，才能给出真正有力量的陪伴。而当你遇见那个值得的人，也请放心地、毫无保留地爱一次。\",\"suggestions\":[\"当一段关系让你感到安全时，试着多打开一点心门，让爱流动起来\",\"用「主动给予」代替「被动防备」：一句关心、一份小惊喜，让关系升温\",\"写下你在爱里害怕的事，直面它，往往能发现它没那么可怕\"]}}}},\"_combos\":{\"eros_ludus\":\"激情与自由的混合体：恋爱初期魅力四射、火花四溅，但也要留意——别让心动永远停留在追逐的游戏里。\",\"eros_storge\":\"火与水的交融：既有一见倾心的冲动，也有细水长流的踏实。你们的爱情剧本通常是「先热后稳」，幸运且少见。\",\"eros_pragma\":\"心动而清醒：会为激情寻找理性的落点，一边被吸引，一边默默评估。适合把浪漫经营成可持续的规划。\",\"eros_mania\":\"炽烈燃烧型：爱得浓烈，也容易患得患失。你的情绪与关系深度绑定，请练习给彼此一点呼吸的空间。\",\"eros_agape\":\"理想主义恋人：把心动转化为毫无保留的付出，浪漫又深情。但请记得，你也同样值得被爱与被呵护。\",\"ludus_eros\":\"玩世不恭的撩拨高手：享受追逐与被追逐的刺激，来去如风。若想要一段长久的关系，需要练习「停下来」。\",\"ludus_storge\":\"表面洒脱、内心渴望安定：不是不想认真，而是一直在等一个真正让你愿意停留的人。\",\"ludus_pragma\":\"理性博弈者：把感情当作一场清醒的权衡，自我保护意识很强，但也要小心别错过真实的亲密。\",\"ludus_mania\":\"忽冷忽热的拉扯型：上一秒想逃离，下一秒又焦虑。建议先安顿好自己的安全感，再谈爱情。\",\"ludus_agape\":\"用游戏掩饰深情：害怕受伤所以先发制人。其实你的温柔一直都在，真诚是你最大的功课。\",\"storge_eros\":\"先友后恋的经典剧本：既有默契又有火花，是很多关系羡慕的起点，请好好珍惜这份难得。\",\"storge_ludus\":\"慢热但通透：你看得清谁值得认真、谁只是过客，不轻易动心，一旦动心就很长情。\",\"storge_pragma\":\"稳重务实派：把感情过成相互托底的生活，平淡、可靠，是长跑型选手。\",\"storge_mania\":\"温柔外壳下的依恋：一旦动心就害怕失去，安全感需要先由自己给足，而非向对方索取。\",\"storge_agape\":\"温厚长情型：朋友般的知己加上无条件的照顾，是这个时代稀缺的「老派人」。\",\"pragma_eros\":\"条件与心动的平衡术：既看现实也看眼缘，择偶眼光很「人间清醒」，容易找到稳定的关系。\",\"pragma_ludus\":\"清醒的观察者：权衡利弊多于心动，警惕爱情变成一场谈判——留一点感性给关系。\",\"pragma_storge\":\"现实又重情：看重长久契合与彼此托底，适合经营稳定、有深度的伴侣关系。\",\"pragma_mania\":\"越理性，越容易在某个人身上失控：一旦认定，会格外执着。请分清「选择」与「执念」。\",\"pragma_agape\":\"计划型付出者：把爱与责任安排得明明白白。责任感是你的底色，也请允许自己偶尔任性。\",\"mania_eros\":\"浓烈的占有之爱：爱到深处全是执念。学会把一部分注意力收回自己身上，关系会更松弛。\",\"mania_ludus\":\"矛盾综合体：既想掌控，又随时准备逃离。请先安顿好自己的内心，再与别人靠近。\",\"mania_storge\":\"用依赖表达在乎：其实你渴望的是确定感。练习在爱里留出边界，你会更安心。\",\"mania_pragma\":\"把焦虑投射到「条件是否合适」：你真正害怕的，或许只是未来的不确定本身。\",\"mania_agape\":\"以牺牲换取安全感：付出越多越怕失去。请记住——健康的爱不是等价交换，你无需用疼痛证明深爱。\",\"agape_eros\":\"浪漫的理想主义者：把爱人捧在手心，眼里有光。也请常常记得，你自己同样值得被捧。\",\"agape_ludus\":\"外冷内热的守望者：看似不在意，其实付出最深。你的深情值得被一个懂你的人接住。\",\"agape_storge\":\"温柔长情的守护者：爱得深且稳，是治愈系的恋人。世界对这样的人，往往会温柔以待。\",\"agape_pragma\":\"有担当的现实主义者：在你这里，爱既是感觉，也是责任与选择——可靠而有力量。\",\"agape_mania\":\"以付出为名的依恋：警惕过度牺牲。学会「被爱」，是比「给予」更重要的功课。\"},\"_lowtips\":{\"eros\":\"浪漫型得分偏低：你可能更看重相处而非外在冲动，对「一见钟情」保持怀疑——这让你少踩很多坑，但也别错过心动的瞬间。\",\"ludus\":\"游戏型得分偏低：你对关系认真、专一，不玩暧昧游戏——这是稀缺的品质，请不必因为「不够洒脱」而怀疑自己。\",\"storge\":\"同伴型得分偏低：你可能不习惯从友情慢慢过渡到爱情，更依赖瞬间的连接。试着给彼此多一点时间，深度了解会有惊喜。\",\"pragma\":\"现实型得分偏低：你恋爱时不太计算条件，更相信感觉本身。保持这份纯粹，也别忘了适当看看「长远匹配」。\",\"mania\":\"占有型得分偏低：你在关系里松弛、有安全感，不轻易被情绪绑架——这是很健康的状态。\",\"agape\":\"奉献型得分偏低：你爱得有所保留、懂得保护自己。平衡感是好事，但偶尔也请放心地付出一次。\"},\"_dims\":{\"eros\":{\"label\":\"浪漫型 Eros\",\"color\":\"#ff4d6d\",\"tag\":\"激情 · 一见钟情\",\"levels\":[{\"min\":29,\"label\":\"倾向明显\",\"desc\":\"你的爱浓烈而外放，一见钟情式的吸引是你的常态，关系进展快、浓度高。\"},{\"min\":22,\"label\":\"中等\",\"desc\":\"你重视心动与吸引，同时保留一份冷静，浪漫与理性在你身上并存。\"},{\"min\":0,\"label\":\"偏低\",\"desc\":\"你更看重相处而非外在冲动，对「一见钟情」保持怀疑——这让你少踩很多坑。\"}]},\"ludus\":{\"label\":\"游戏型 Ludus\",\"color\":\"#ff9f1c\",\"tag\":\"享乐 · 自由多变\",\"levels\":[{\"min\":29,\"label\":\"倾向明显\",\"desc\":\"你视爱情为一场轻松的游戏，享受追逐与自由，不喜欢被承诺束缚。\"},{\"min\":22,\"label\":\"中等\",\"desc\":\"你能在投入与洒脱之间切换，懂得享受关系，也不轻易被绑住。\"},{\"min\":0,\"label\":\"偏低\",\"desc\":\"你对关系认真、专一，不玩暧昧游戏——这是稀缺的品质。\"}]},\"storge\":{\"label\":\"同伴型 Storge\",\"color\":\"#2ec4b6\",\"tag\":\"友情 · 细水长流\",\"levels\":[{\"min\":29,\"label\":\"倾向明显\",\"desc\":\"你的爱从友谊里长出来，信任时间与了解，最珍惜细水长流的默契。\"},{\"min\":22,\"label\":\"中等\",\"desc\":\"你既能享受友情的铺垫，也期待日久生情的安定感。\"},{\"min\":0,\"label\":\"偏低\",\"desc\":\"你可能更依赖瞬间的连接，不习惯从友情慢慢过渡到爱情。\"}]},\"pragma\":{\"label\":\"现实型 Pragma\",\"color\":\"#3a86ff\",\"tag\":\"理性 · 条件匹配\",\"levels\":[{\"min\":29,\"label\":\"倾向明显\",\"desc\":\"你的爱是清醒的选择，理性衡量背景、规划与未来，追求门当户对的契合。\"},{\"min\":22,\"label\":\"中等\",\"desc\":\"你在感性与理性之间保持平衡，既看感觉也看长远匹配。\"},{\"min\":0,\"label\":\"偏低\",\"desc\":\"你恋爱时不太计算条件，更相信感觉本身——纯粹而珍贵。\"}]},\"mania\":{\"label\":\"占有型 Mania\",\"color\":\"#9b5de5\",\"tag\":\"浓烈 · 患得患失\",\"levels\":[{\"min\":29,\"label\":\"倾向明显\",\"desc\":\"你爱得浓烈、在意深切，对方的回应会牵动你的全部情绪——请练习把安全感还给自己。\"},{\"min\":22,\"label\":\"中等\",\"desc\":\"你情感浓度较高，偶尔会患得患失，但大体能够自处。\"},{\"min\":0,\"label\":\"偏低\",\"desc\":\"你在关系里松弛、有安全感，不轻易被情绪绑架——这是很健康的状态。\"}]},\"agape\":{\"label\":\"奉献型 Agape\",\"color\":\"#f15bb5\",\"tag\":\"无私 · 无条件付出\",\"levels\":[{\"min\":29,\"label\":\"倾向明显\",\"desc\":\"你习惯把对方放在自己之前，无条件付出——请记得，你也同样值得被爱。\"},{\"min\":22,\"label\":\"中等\",\"desc\":\"你愿意为对方付出，同时保留着照顾自己的意识。\"},{\"min\":0,\"label\":\"偏低\",\"desc\":\"你爱得有所保留、懂得保护自己——平衡是好事，偶尔也请放心地付出一次。\"}]}},\"_balance\":{\"均衡型 · 六色混色\":{\"desc\":\"你的六种爱情色彩得分接近，说明你的爱会随情境与对象流动——今天可以是浓烈的，明天可以是温柔的。这种「混色」让你适应力强，但也建议你留意：自己真正想要的关系底色是什么。\"},\"主导型 · 色彩分明\":{\"desc\":\"你有一个比较清晰的主导色彩，同时保留着其他色彩的底色。这样的你，爱得有主线、不迷失，是六边形里「有重心」的形状。\"},\"聚焦型 · 主色鲜明\":{\"desc\":\"你的爱情光谱高度聚焦于一种颜色，其他色彩明显靠后。你爱得很「纯粹」，但也要小心：单一的色彩可能让关系缺少回旋的余地。\"}}}}','published',2,1,'2026-08-24 23:50:43.023','2026-08-25 15:05:01.841',0),(3,'qinzi','亲子学业压力沟通测评','Parent-Child Communication Test','亲子测评','从亲子沟通情况、学业焦虑、心理韧性三个维度，帮助您看见孩子学业压力下的情绪状态，找到更温暖的沟通方式。','本测评共 34 题，分为「亲子沟通情况」「学业焦虑」「心理韧性」三个部分，请按提示逐部分作答，以您与孩子相处的真实情况为准，没有对错之分。','#BC6E43','heart','[{\"id\":\"qz_comm_1\",\"type\":\"scale\",\"title\":\"我允许孩子在一些事情上和我有不同意见\",\"dimension\":\"comm\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_2\",\"type\":\"scale\",\"title\":\"和孩子谈家庭规则或安排时，我会让孩子参与讨论\",\"dimension\":\"comm\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_3\",\"type\":\"scale\",\"title\":\"和孩子谈事情时，我会主动询问孩子的看法\",\"dimension\":\"comm\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_4\",\"type\":\"scale\",\"title\":\"和孩子讨论事情时，我常常坚持自己说了算\",\"dimension\":\"comm\",\"required\":true,\"reverse\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_5\",\"type\":\"scale\",\"title\":\"我鼓励孩子表达不同意见，并说明自己的理由\",\"dimension\":\"comm\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_6\",\"type\":\"scale\",\"title\":\"我会鼓励孩子从不同角度看问题\",\"dimension\":\"comm\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_7\",\"type\":\"scale\",\"title\":\"孩子愿意告诉我他在想什么\",\"dimension\":\"comm\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_8\",\"type\":\"scale\",\"title\":\"孩子不认同我的观点时，我通常会很生气\",\"dimension\":\"comm\",\"required\":true,\"reverse\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_9\",\"type\":\"scale\",\"title\":\"孩子做得不好时，我会先批评，而不是先了解原因和想法\",\"dimension\":\"comm\",\"required\":true,\"reverse\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_10\",\"type\":\"scale\",\"title\":\"我和孩子会谈论彼此的感受和情绪\",\"dimension\":\"comm\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_lie\",\"type\":\"scale\",\"title\":\"为确保您在认真阅读每道题，本题请直接选择「非常符合」\",\"dimension\":\"comm\",\"required\":true,\"lie\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_11\",\"type\":\"scale\",\"title\":\"即使意见不一致，孩子也愿意和我讲话\",\"dimension\":\"comm\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_comm_12\",\"type\":\"scale\",\"title\":\"即使不同意孩子的观点，我也愿意认真听他说完\",\"dimension\":\"comm\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"完全不符合\",\"maxLabel\":\"非常符合\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"完全不符合\"},{\"value\":\"2\",\"label\":\"比较不符合\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"比较符合\"},{\"value\":\"5\",\"label\":\"非常符合\"}]},{\"id\":\"qz_anx_1\",\"type\":\"scale\",\"title\":\"孩子学习时经常心不在焉、注意力难以集中，让我感到苦恼\",\"dimension\":\"anx\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"从不\",\"maxLabel\":\"总是\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"从不\"},{\"value\":\"2\",\"label\":\"有时\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"经常\"},{\"value\":\"5\",\"label\":\"总是\"}]},{\"id\":\"qz_anx_2\",\"type\":\"scale\",\"title\":\"我担心自己的能力不足，无法为孩子提供更好的教育支持\",\"dimension\":\"anx\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"从不\",\"maxLabel\":\"总是\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"从不\"},{\"value\":\"2\",\"label\":\"有时\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"经常\"},{\"value\":\"5\",\"label\":\"总是\"}]},{\"id\":\"qz_anx_3\",\"type\":\"scale\",\"title\":\"想到自己无法为孩子提供更多或更好的教育资源，我会感到心烦\",\"dimension\":\"anx\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"从不\",\"maxLabel\":\"总是\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"从不\"},{\"value\":\"2\",\"label\":\"有时\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"经常\"},{\"value\":\"5\",\"label\":\"总是\"}]},{\"id\":\"qz_anx_4\",\"type\":\"scale\",\"title\":\"孩子临近重要考试时，我比平时更容易紧张和焦躁\",\"dimension\":\"anx\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"从不\",\"maxLabel\":\"总是\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"从不\"},{\"value\":\"2\",\"label\":\"有时\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"经常\"},{\"value\":\"5\",\"label\":\"总是\"}]},{\"id\":\"qz_anx_5\",\"type\":\"scale\",\"title\":\"孩子学习态度不够认真时，我会感到着急，甚至忍不住批评他\",\"dimension\":\"anx\",\"required\":true,\"scaleConfig\":{\"min\":1,\"max\":5,\"minLabel\":\"从不\",\"maxLabel\":\"总是\",\"type\":\"number\"},\"options\":[{\"value\":\"1\",\"label\":\"从不\"},{\"value\":\"2\",\"label\":\"有时\"},{\"value\":\"3\",\"label\":\"一般\"},{\"value\":\"4\",\"label\":\"